const updateKB = `-- name: UpdateKB :execrows
UPDATE kb_repos SET name = ?1, description = ?2, repo = ?3, base_branch = ?4,
  space_role = ?5, entry_instructions = ?6, validator_json = ?7,
  write_policy = ?8, allowed_roles_json = ?9, max_sessions = ?10,
  idle_sleep_seconds = ?11, request_timeout_seconds = ?12,
  session_ttl_seconds = ?13, enabled = ?14, updated_at = ?15, version = version + 1
WHERE id = ?16 AND version = ?17
`

type UpdateKBParams struct {
	Name                  string
	Description           string
	Repo                  string
	BaseBranch            string
	SpaceRole             string
	EntryInstructions     string
	ValidatorJson         string
	WritePolicy           string
	AllowedRolesJson      string
	MaxSessions           int64
	IdleSleepSeconds      int64
	RequestTimeoutSeconds int64
	SessionTtlSeconds     int64
	Enabled               int64
	Now                   int64
	ID                    string
	Version               int64
}

func (q *Queries) UpdateKB(ctx context.Context, arg UpdateKBParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateKB,
		arg.Name,
		arg.Description,
		arg.Repo,
		arg.BaseBranch,
		arg.SpaceRole,
		arg.EntryInstructions,
		arg.ValidatorJson,
		arg.WritePolicy,
		arg.AllowedRolesJson,
		arg.MaxSessions,
		arg.IdleSleepSeconds,
		arg.RequestTimeoutSeconds,
		arg.SessionTtlSeconds,
		arg.Enabled,
		arg.Now,
		arg.ID,
		arg.Version,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
